int main(void) {
    int score = 10;
    int lives = 3;
    int hits = 4;
    int combo;

    score += 5;
    score *= 2;
    lives--;
    printf("%d %d\n", score, lives);

    combo = hits++;
    printf("%d %d\n", combo, hits);
    combo = ++hits;
    printf("%d %d\n", combo, hits);
    combo = hits = 0;
    printf("%d %d\n", combo, hits);
    return 0;
}

